I was porting https://love2d.org/wiki/Tutorial:Physics to TypeScript and noticed that the third parameter for `love.window.setMode` is optional in Lua

<details>
<summary>TypeScript port</summary>

```ts
import { World, Body, Shape, Fixture, PolygonShape, CircleShape } from "love.physics"

let world: World
let objects: Objects // table to hold all our physical objects

type Objects = {
  ground: Object<PolygonShape>
  ball: Object<CircleShape>
  block1: Object<PolygonShape>
  block2: Object<PolygonShape>
}

type Object<S extends Shape> = {
  body: Body
  shape: S
  fixture: Fixture
}

love.load = () => {
  // the height of a meter our worlds will be 64px
  love.physics.setMeter(64)
  // create a world for the bodies to exist in with horizontal gravity
  // of 0 and vertical gravity of 9.81
  world = love.physics.newWorld(0, 9.81*64, true)

  // let's create the ground
  let ground: Object<PolygonShape>
  {
    // remember, the shape (the rectangle we create next) anchors to the
    // body from its center, so we have to move it to (650/2, 650-50/2)
    const body = love.physics.newBody(world, 650/2, 650-50/2)
    // make a rectangle with a width of 650 and a height of 50
    const shape = love.physics.newRectangleShape(650, 50)
    // attach shape to body
    const fixture = love.physics.newFixture(body, shape)
    ground = {body, shape, fixture}
  }

  // let's create a ball
  let ball: Object<CircleShape>
  {
    // place the body in the center of the world and make it dynamic, so
    // it can move around
    const body = love.physics.newBody(world, 650/2, 650/2, "dynamic")
    // the ball's shape has a radius of 20
    const shape = love.physics.newCircleShape(20)
    // Attach fixture to body and give it a density of 1.
    const fixture = love.physics.newFixture(body, shape, 1)
    fixture.setRestitution(0.9) // let the ball bounce
    ball = {body, shape, fixture}
  }

  // let's create a couple blocks to play around with
  let block1: Object<PolygonShape>
  {
    const body = love.physics.newBody(world, 200, 550, "dynamic")
    const shape = love.physics.newRectangleShape(0, 0, 50, 100)
    // A higher density gives it more mass.
    const fixture = love.physics.newFixture(body, shape, 5)
    block1 = {body, shape, fixture}
  }

  let block2: Object<PolygonShape>
  {
    const body = love.physics.newBody(world, 200, 400, "dynamic")
    const shape = love.physics.newRectangleShape(0, 0, 100, 50)
    const fixture = love.physics.newFixture(body, shape, 2)
    block2 = {body, shape, fixture}
  }

  objects = {ground, ball, block1, block2}

  // initial graphics setup
  // set the background color to a nice blue
  love.graphics.setBackgroundColor(0.41, 0.53, 0.97)
  love.window.setMode(650, 650, {}) // set the window dimensions to 650 by 650
  // TODO: make flags parameter optional
}

love.update = (dt: number) => {
  world.update(dt) // this puts the world into motion

  // here we are going to create some keyboard events
  // press the right arrow key to push the ball to the right
  if (love.keyboard.isDown("right")) {
    objects.ball.body.applyForce(400, 0)
  // press the left arrow key to push the ball to the left
  } else if (love.keyboard.isDown("left")) {
    objects.ball.body.applyForce(-400, 0)
  // press the up arrow key to set the ball in the air
  } else if (love.keyboard.isDown("up")) {
    objects.ball.body.setPosition(650/2, 650/2)
    // we must set the velocity to zero to prevent a potentially large
    // velocity generated by the change in position
    objects.ball.body.setLinearVelocity(0, 0)
  }
}

love.draw = () => {
  // set the drawing color to green for the ground
  love.graphics.setColor(0.28, 0.63, 0.05)
  // draw a "filled in" polygon using the ground's coordinates
  love.graphics.polygon("fill", objects.ground.body.getWorldPoints(
                           ...objects.ground.shape.getPoints()))

  // set the drawing color to red for the ball
  love.graphics.setColor(0.76, 0.18, 0.05)
  love.graphics.circle("fill", objects.ball.body.getX(),
                       objects.ball.body.getY(), objects.ball.shape.getRadius())

  // set the drawing color to grey for the blocks
  love.graphics.setColor(0.20, 0.20, 0.20)
  love.graphics.polygon("fill", objects.block1.body.getWorldPoints(
                           ...objects.block1.shape.getPoints()))
  love.graphics.polygon("fill", objects.block2.body.getWorldPoints(
                           ...objects.block2.shape.getPoints()))
}
```

